SELECT jst_3205_f5258 AS workfilepjname, jst_3205_f5257 AS workfileproject, jst_3205_f5264 AS workfileprojectamout, jst_3205_f6254 As workGPMForecast FROM jst_3205
AND jst_3205_f5257 IN
#{project}

SELECT a.jst_3124_f5170 AS workfilepjname, a.jst_3124_f5171 AS workfileproject, SUM(b.jst_3126_f4036) AS workfileamount FROM jst_3124 a JOIN jst_3126 b ON a.jst_3124_id = b.jst_3126_FOREIGNKEY JOIN jsf_work w ON w.WORKRECORD_ID = a.jst_3124_id
AND COALESCE(a.jst_3124_f6228, w.WORKDONEWITHDATE) BETWEEN #{workFileDoneStartTime} AND #{workFileDoneEndTime}
AND a.jst_3124_f5171 IN
#{project}
AND w.WORKSTATUS=100 AND w.WF_CUREMPLOYEE_ID=a.jst_3124_owner AND w.WORKFILETYPE NOT LIKE '%FZY%'
GROUP BY a.jst_3124_f5171
